import{_ as s,H as t,f as a,i}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"05 | 药到病除：知识库机器人常见的三大病症与解药","description":"","frontmatter":{},"headers":[{"level":2,"title":"问题 1： 明明在知识库中有答案，就是回答不出来！","slug":"问题-1-明明在知识库中有答案-就是回答不出来","link":"#问题-1-明明在知识库中有答案-就是回答不出来","children":[{"level":3,"title":"原因 1：检索方式不合理","slug":"原因-1-检索方式不合理","link":"#原因-1-检索方式不合理","children":[]},{"level":3,"title":"原因 2: 分块不合理","slug":"原因-2-分块不合理","link":"#原因-2-分块不合理","children":[]}]},{"level":2,"title":"问题 2：怎么把说明书中的图片带出来回答？","slug":"问题-2-怎么把说明书中的图片带出来回答","link":"#问题-2-怎么把说明书中的图片带出来回答","children":[]},{"level":2,"title":"问题 3：Token 消耗太快了，有没有什么降低成本的方法？","slug":"问题-3-token-消耗太快了-有没有什么降低成本的方法","link":"#问题-3-token-消耗太快了-有没有什么降低成本的方法","children":[]},{"level":2,"title":"产品复盘","slug":"产品复盘","link":"#产品复盘","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"成为AGI产品经理/05｜药到病除：知识库机器人常见的三大病症与解药.md","filePath":"成为AGI产品经理/05｜药到病除：知识库机器人常见的三大病症与解药.md","lastUpdated":1795557342000}'),n={name:"成为AGI产品经理/05｜药到病除：知识库机器人常见的三大病症与解药.md"};function p(l,e,o,h,g,r){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="_05-药到病除-知识库机器人常见的三大病症与解药" tabindex="-1">05 | 药到病除：知识库机器人常见的三大病症与解药 <a class="header-anchor" href="#_05-药到病除-知识库机器人常见的三大病症与解药" aria-label="Permalink to &quot;05 | 药到病除：知识库机器人常见的三大病症与解药&quot;">​</a></h1><p>你好，我是产品二姐。</p><p>这节课，我们来聊聊“消费品使用问答助手”落地过程中遇到的问题和解决方法。</p><p>在这个产品里我们核心用的技术是 RAG，对于希望转型到 AI 产品经理的同学来说，从 RAG入门会比较容易，但同时也要明白，RAG 做深很难，就连 OpenAI 的工程师都说 “RAG 比想象中难”。所以这节课，我选择先从最棘手问题入手，然后逐个分析引起这些问题的原因和方法。</p><p>我先用一张“诊断表”来列出在 &lt; 消费品使用问答助手 &gt; 中遇到的问题，然后逐一定位问题的成因，以及它们在 RAG 流程中的位置，最终制定解决方案。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/1.png" alt=""></a></p><h2 id="问题-1-明明在知识库中有答案-就是回答不出来" tabindex="-1">问题 1： 明明在知识库中有答案，就是回答不出来！ <a class="header-anchor" href="#问题-1-明明在知识库中有答案-就是回答不出来" aria-label="Permalink to &quot;问题 1： 明明在知识库中有答案，就是回答不出来！&quot;">​</a></h2><p>下图是“消费品使用问答助手”的真实问题，当用户问，“在人机对话时，机器识别不到讲的语音怎么办”。我们肉眼可见在上传的产品说明书里有一个极其贴切的回答：“a. 需要点击对话键，激活对话功能……”。然而，AI 问答助手却给出了非常笼统的回答：“可能多种原因导致的，比如环境噪音……”</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/2.png" alt=""></a></p><p>相信这时你也会困惑。别着急，我们由表及里一项项检查。</p><p>我们知道，RAG 中的内容主要由用户请求和检索到的文本块组成。所以首先要看我们期待的文本块有没有被检索出来。通过 Dify 里的 Tracing 功能我们看到，这里并没有检索出我们期待的文本块。之所以出现这种问题，一般会有两个原因：一是检索方式不合理，二是分块不合理。我们来分别排查。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/3.png" alt=""></a></p><h3 id="原因-1-检索方式不合理" tabindex="-1">原因 1：检索方式不合理 <a class="header-anchor" href="#原因-1-检索方式不合理" aria-label="Permalink to &quot;原因 1：检索方式不合理&quot;">​</a></h3><p>在第一章第三节中的 RAG 技术原理中，我们曾经讲过 RAG 中的一个环节是知识检索。好比是你去一个巨大的图书馆里快速找到你要的资料。假如这个图书馆里的书籍只能通过书名来检索，而你用作者名称检索，那么你就很难找到相应的资料。这就是所谓的“检索方式不合理”。这个问题放在 RAG 流水线中处于第五步（如下图）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/4.png" alt=""></a></p><p>在 RAG 里，常见的检索方式有：向量检索、关键词检索、混合检索。</p><ul><li>向量检索</li></ul><p>向量检索就是将用户问题对应的向量与知识库中文本块对应的向量进行比较，距离相近的向量会被选中，也是我们在这个案例中使用的检索方式（Dify 界面中可以设置）。</p><p>举个例子，在现实生活中，你可能会觉得“桃子”与“梨”这两个词完全没有重合，但是在向量空间里，他们之间的距离是非常近的。因为词的向量化就是把一个词拆解为到几百甚至几千个维度，比如形状、大小、类型、颜色等等。</p><p>由于“桃子”与“梨”在很多维度相似，比如都是水果，因此它们在向量空间里非常接近，甚至比“梨”与“梨树”之间的距离更近，所以当我们用向量检索来寻找与“梨”接近的词时，排在第一位的可能是“桃子”，而不是“梨树”。</p><p>同理，假设用户的问题是：</p><ul><li>在人机对话时，机器识别不到讲的语音怎么办</li></ul><p>我们希望被检索到的块对应的文字是：</p><ul><li>问题：在人机对话时，机器识别不到讲的语音回答：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a.需要点击对话键，激活对话功能。在对话过程中，记住一条:当听到机器“叮”一声后，机器处于收音状态，可</span></span>
<span class="line"><span>b.机器说话时，断断续续，或者反应慢，可能是网络信号不太好，请把机器放在信号较强并稳定的区域。</span></span>
<span class="line"><span>c.把路由器和猫都断电，就是电源拔掉，过一会再插上。</span></span></code></pre></div><p>尽管用户的问题完全被包含在文本块中，但因为文本块是作为一个整体放在向量空间里的，二者的距离就会比较远。因此当我们单纯使用向量检索时，这个文本块就不会被检索出来。</p><ul><li>关键字检索</li></ul><p>顾名思义，就是进行关键字匹配，也是传统互联网常用的文本检索方式。这种方法就可以用“梨”来检索“梨树”，但比较死板，要求用户的问题与知识库中的文字完全匹配才行。虽然我们可以采用分词等方法将用户问题拆分为几个关键词分别检索，扩大检索范围。但关键词检索不能理解用户语义，很可能会返回完全不相关的结果，出现我们之前的“人工智障”现象。</p><ul><li>混合检索</li></ul><p>混合检索综合了关键字和向量检索的优势，这也是 RAG 中比较推荐的做法。</p><p>在针对这个特定问题，当我们把检索方法从向量检索改为混合检索后（Dify 里可以很方便的配置检索方式），就解决了。</p><p>那么是不是检索到对应的文本块，就会完全消除这一问题呢？也不是。我们来看导致类似问题的另外一个常见原因： 分块不合理。</p><h3 id="原因-2-分块不合理" tabindex="-1">原因 2: 分块不合理 <a class="header-anchor" href="#原因-2-分块不合理" aria-label="Permalink to &quot;原因 2: 分块不合理&quot;">​</a></h3><p>这个原因处于 RAG 流水线中的第二步：分块。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/5.png" alt=""></a></p><p>还是拿这个例子来说，在下图中，我们看到了匹配的检索结果，但回答仍然不准确。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/6.png" alt=""></a></p><p>如果仔细看图，你就会发现，返回的文本块内容里只有问题（黄色高亮部分），没有回答内容，所以我们把文本块和用户问题都发给模型，模型也无法知道正确答案，只能胡编一个。在Dify 的知识库里，我们检查对应的文本块后发现，问题和回答果然被分在了两个块里，如果把它们合在一起，就能像下图一样返回正确答案了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/7.png" alt=""></a></p><p>在 03 课里，我们讲过 RAG 中的分块方式有很多种，可以说 RAG 中没有最好的分块方式，只有最合理的分块方式，必要的时候我们也需要进行手动修改。在类似 &lt; 消费品使用问答助手&gt; 的产品中，我们就可以在 Dify 里手动把常见问答作为一个整体放在一个块里。</p><p>但问答场景有非常多的情况，我们不可能每个都去手动调整，还有什么方法可以弥补分块不合理导致错误呢？</p><ul><li>方法 1：分块时设置一定的冗余重合内容</li></ul><p>如下图所示，我们可以将上一个文本块的一部分内容同时也放在下一个文本块中，我们推荐重叠部分占文本块整个长度的 15% 左右 (可以在 Dify 里设置)。这样，就会在一定程度上提升了文本块语义完整性、关联度，从而进一步提升准确度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/8.png" alt=""></a></p><ul><li>方法 2：强制返回相邻文本块</li></ul><p>如下图，如果知识库检索返回了文本块 2，我们可以强制在代码里返回文本块 2 以及它相邻的文本块 1 和 3，这样降低了语义被切断的可能性。不过这样做会将 Token 的消耗成本扩大 2-3倍，我们明白这点后在产品中要做适当取舍。这块需要有开发同学通过代码来搞定。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/9.png" alt=""></a></p><ul><li>方法 3：改进分块方法</li></ul><p>前两种方法是从使用角度改进，第三种方法就是改变分块本身。针对不同类型的文档选择不同的分块方法，原则是：尽量保持原有语义的完整度。在这里我用一个表格来列举常见的文档类型对应的分块方法以及注意事项作为参考，实际中你可以根据自身情况灵活选择。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/10.png" alt=""></a></p><p>以上就是可能引发“有答案，但回答不出来” 这个问题的常见的两个原因，实际中还可能有其他原因，但无论什么原因，追溯方法都是类似的。我们总结一下解决方法。</p><ol><li><p>先看检索结果，如果检索结果不对，则修正检索方法或者对检索词做一定处理。</p></li><li><p>检索结果正确的情况下，看分块内容是否完全覆盖答案。</p></li><li><p>如果分块也正确，就可以优化大语言模型的提示词，或者切换更高阶的大语言模型。</p></li></ol><p>其中，最后一点更考察提示词和大语言模型本身的质量，我们在这个案例里不做详述。接下来，让我们看看其他问题。</p><h2 id="问题-2-怎么把说明书中的图片带出来回答" tabindex="-1">问题 2：怎么把说明书中的图片带出来回答？ <a class="header-anchor" href="#问题-2-怎么把说明书中的图片带出来回答" aria-label="Permalink to &quot;问题 2：怎么把说明书中的图片带出来回答？&quot;">​</a></h2><p>在 &lt; 消费品使用问答助手 &gt; 这个场景中，产品说明书中经常会有类似下面的示意图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/11.png" alt=""></a></p><p>但在 RAG 向量化处理的时候，是无法把文本和图片放在同一向量库中的，因此我们无法像文字那样把图片也检索出来。事实上，图片和文字在向量空间的统一化表征目前还是 AI 的难题。</p><p>那么当我们需要在回答时展现图片该怎么操作呢？这里提供两种方法，我称之为“图文关联法”和“图文转换”法，二者可以结合使用。它们位于 RAG 流水线的第一步：数据提取。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/12.png" alt=""></a></p><ul><li>方法 1：图文关联法</li></ul><p>在 RAG 中，每个文本分块都有自己的元数据（Metadata），元数据存储的是分块自身的信息，比如文本块的来源、大小、作者等。元数据里存储哪些数据是可以定制的，我们就可以增加一个 ImageURL 的字段，当文本块里的文字内容需要使用图片来回答时，就可以同时读取对应文本块里的 ImageURL 信息，将图片保留到答案中。这个过程需要由开发同学在向量数据中写入，写入后向量的 meta data 中就保留了对应的信息（如下图）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/13.png" alt=""></a></p><ul><li>方法 2： 图文转换法</li></ul><p>顾名思义，就是将图片信息转换为文字信息，我们可以利用高阶多模态大模型，比如 GoogleGemini1.5，将图片内容理解后转换为文本 (如下图)，将该文本块作为知识库的一部分，并将ImageURL 存储为该文本块的元数据中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/14.png" alt=""></a></p><p>以上两个问题是解决“消费品产品小助手”中的功能性问题（有答案无回答，答案中带出说明书），接下来是一个成本优化的问题。</p><h2 id="问题-3-token-消耗太快了-有没有什么降低成本的方法" tabindex="-1">问题 3：Token 消耗太快了，有没有什么降低成本的方法？ <a class="header-anchor" href="#问题-3-token-消耗太快了-有没有什么降低成本的方法" aria-label="Permalink to &quot;问题 3：Token 消耗太快了，有没有什么降低成本的方法？&quot;">​</a></h2><p>我们上节课提到，对企业来说，采用 AI 工具有一个重要的诉求就是降低成本。如果我们降低了人力成本，但增加了大模型的调用成本，难免会让成本此消彼长。所以，我也来介绍几种降低成本的方法。这两种方法都属于 RAG 流水线中的第九步：LLM 归纳环节。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/15.png" alt=""></a></p><ul><li>方法 1：用问答对匹配代替 RAG 减少大模型调用次数</li></ul><p>如下图中的红色部分所示，我们可以在企业售后端构建一个问答对数据库，存储用户的常见问题。当用户提问时，首先与数据库里的问题进行进行语义检索（类似 RAG 的混合检索方案），如果相似度大于某个阈值，则将该问题对应的答案直接返回给用户，而无需再经过大语言模型生成。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/16.png" alt=""></a></p><p>按照 80-20 原则，20% 的问题可以覆盖到 80% 的用户问题，当我们将这 20% 的问题存储在问答对中，就能节省 80% 的成本。</p><ul><li>方法 2：压缩提示，降低 token 量</li></ul><p>我们知道，RAG 的机制就是检索到疑似相关内容发给大模型总结，那么这里的“相关内容”往往就带有非常多的冗余信息，换句话说，提示词的压缩空间很大。目前提示词压缩方法在学术界有很多尝试，比如微软的 LLMLingua 可以使提示词压缩 30% 左右，他们在模型开源社区有demo，你可以去这个链接试试。</p><p>不过压缩提示词也意味着信息丢失，会影响最终返回的准确率。另外压缩提示词本身是通过调用小模型实现的，本身也意味着成本消耗。所以采用这个策略时不仅要多次尝试，还要多算账。</p><p>到这里我们就解决了 RAG 中的三个常见问题。实际中你可能还会遇到其他问题，但是你只要牢记 RAG 流水线的各个环节，一项项排查，总能定位发生在哪个环节，然后由这个环节出发来搜索解决方案，就会比直接由问题出发寻求解决方案会更高效。</p><h2 id="产品复盘" tabindex="-1">产品复盘 <a class="header-anchor" href="#产品复盘" aria-label="Permalink to &quot;产品复盘&quot;">​</a></h2><p>好了，我们总结一下在 &lt; 产品使用问答助手 &gt; 这个产品中遇到实战问题以及解决方法，在开头的那张诊断表里，我们也可以圆满的写上一副“对症良方”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/05/17.png" alt=""></a></p><p>当然，这个产品中除了使用 RAG 技术实现机器人问答之外，还有两个功能是评估人工回答质量和给用户问题打标签，这两项中主要使用到的技术就是提示词技巧，也是我们下个案例中的主攻内容，在这里我们简单呈现。</p><p>评估人工回答质量的提示词如下：</p><ul><li>你是一位优秀的客服人员，我会给你提供一组用户和客服人员的对话，你来对这个回答进行公正、严格的打分。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 评分标准</span></span>
<span class="line"><span>1. 相关度： 评价回答是否和用户问题相关。评分标准为：1分--回答与问题完全不相关；2分--回答与问题少</span></span>
<span class="line"><span>2. 用户满意度：评价用户是否对回答满意。评分标准为：1分--非常不满意；2分--不满意；3分--勉强接受</span></span>
<span class="line"><span>## 输出格式</span></span></code></pre></div><ul><li>请严格按照以下格式输出：</li></ul><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;相关度&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">：4</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;"> ,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;用户满意度&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">## 对话</span></span></code></pre></div><ul><li>我给你的对话是：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{对话}</span></span>
<span class="line"><span>##评分结果是：</span></span></code></pre></div><p>给用户问题打标签提示词如下：</p><ul><li>你是一位极具洞察力的产品设计师，我会给你提供一组用户和客服人员的对话，你从这些对话中探查用户诉求，</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 标签选项</span></span>
<span class="line"><span>1. 运输不当：和快递相关的问题，比如物流太慢，包装破损、简陋、有污渍，发错货。</span></span>
<span class="line"><span>2. 操作不便：和产品操作相关的问题，比如操作不方便，操作流程复杂。</span></span>
<span class="line"><span>3. 质量问题：产品到货后不能开机，无法使用。</span></span>
<span class="line"><span>4. 新功能诉求：比如希望能支持新内容，新功能等。</span></span>
<span class="line"><span>## 输出格式</span></span></code></pre></div><ul><li>请严格按照以下格式输出：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>&quot;运输不当&quot;,&quot;操作不便&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>## 对话</span></span></code></pre></div><ul><li>我给你的对话是：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{对话}</span></span>
<span class="line"><span>##标签：</span></span></code></pre></div><p>到这里，我们的第一个实战案例就结束了。我们重点讲述 RAG 在产品中的应用和常见问题。相信通过实践，你会对 RAG 有了更深的理解和体会。</p><p>那么 AI 上层建筑中的另外两项技术，提示词和 Agent 又可以应用在哪些场景呢？除了我们最常见的对话机器人形态，还会有哪些产品形态呢？</p><p>在下一节中，我们就会重点利用提示词工程来做一个文本数据提取分析工具，ta 可以帮助用户从文本数据中提取有效信息，并对这些信息进行分析、洞察。在这里我也顺便给你出一个简单的题目预习、热身一下提示词工程。请你写一段提示词来识别用户所说时间。要求是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给定一个描述时间点的短语和参照时间，按照YYYY-MM-DD HH:MM:SS格式输出这个短语对应的时间。比如：</span></span>
<span class="line"><span>描述时间点的短语是：“昨天这个时候”</span></span>
<span class="line"><span>参照时间是：“2024-08-08 12:34:12”</span></span>
<span class="line"><span>输出：{&quot;time&quot;: 2024-08-07 12:34:12}</span></span></code></pre></div><p>我给你的时间短语有：</p><ul><li>明天昨天下周上个月两天前三小时后去年同一天下个月的这个时候两周后上周二明年夏天去年冬天在午夜大约中午几分钟后半小时前到今天结束时一大早</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>再过100小时</span></span></code></pre></div><p>在下节课开始之前，你先感受一下吧。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>下次你家再买电子消费品的时候，要不要把对应的电子说明书改成“智能说明书”呢？你甚至还可以在 Coze 或者 Dify 里搭建完之后发布在微信小号上，放在家庭群里，这样就有个家电消费品小助手啦。</p><p>欢迎分享你的小助手，在留言区和我交流搭建、使用心得。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。我们下节课见！</p><blockquote><blockquote><p>戳此加入课程交流群</p></blockquote></blockquote>`,107)])])}const E=s(n,[["render",p]]);export{u as __pageData,E as default};
